package logsvc

import "log"

func ProcessOrder(id int, amount float64) error {
	if id <= 0 {
		log.Printf("invalid order id: %d", id)
		return ErrInvalidID
	}
	if amount <= 0 {
		log.Printf("invalid amount: %f", amount)
		return ErrInvalidAmount
	}
	log.Printf("processing order id=%d amount=%.2f", id, amount)
	return nil
}

var ErrInvalidID = errorf("invalid id")
var ErrInvalidAmount = errorf("invalid amount")

type appError struct{ msg string }

func (e *appError) Error() string { return e.msg }

func errorf(msg string) error { return &appError{msg: msg} }

package logsvc

import "testing"

func TestProcessOrderValid(t *testing.T) {
	if err := ProcessOrder(1, 99.99); err != nil {
		t.Fatalf("expected nil, got %v", err)
	}
}

func TestProcessOrderInvalidID(t *testing.T) {
	if err := ProcessOrder(0, 10.0); err != ErrInvalidID {
		t.Fatalf("expected ErrInvalidID, got %v", err)
	}
}

func TestProcessOrderInvalidAmount(t *testing.T) {
	if err := ProcessOrder(1, -5.0); err != ErrInvalidAmount {
		t.Fatalf("expected ErrInvalidAmount, got %v", err)
	}
}

func TestProcessOrderZeroAmount(t *testing.T) {
	if err := ProcessOrder(1, 0); err != ErrInvalidAmount {
		t.Fatalf("expected ErrInvalidAmount, got %v", err)
	}
}

func TestProcessOrderNegativeID(t *testing.T) {
	if err := ProcessOrder(-1, 10.0); err != ErrInvalidID {
		t.Fatalf("expected ErrInvalidID, got %v", err)
	}
}
